{"action":"shell","command":"cd /testbed && cat > tests/test_smoke.py <<'EOF'
"""Tests for smoke.add (spec 001-transactions, US1/US2).

Covers R01 (integer addition) and R02 (negative integers, zero, floats,
mixed int/float operands).
"""

from smoke import add


# --- US1: integer addition (R01) ---

def test_add_positive_ints():
    assert add(1, 2) == 3


def test_add_positive_ints_large():
    assert add(5, 7) == 12


# --- US2: negative integers, zero, floats (R02) ---

def test_add_negative_int():
    assert add(-3, 5) == 2


def test_add_negative_plus_negative():
    assert add(-2, -3) == -5


def test_add_zero():
    assert add(0, 4) == 4


def test_add_floats():
    assert add(1.5, 2.25) == 3.75


def test_add_negative_float():
    assert add(-1.5, 0.5) == -1.0


def test_add_int_float_mixed():
    assert add(1, 2.5) == 3.5


def test_add_zero_float():
    assert add(0, 2.5) == 2.5
EOF
PYTHONPATH=src:. python3 -m pytest -o addopts="" tests/test_smoke.py -v 2>&1 | tail -14; echo "GREEN-US2-EXIT:$?""}
